// The Rails -> React prop contract.
//
// Everything here is built by Rails and arrives already resolved: labels are translated, URLs are
// generated by the router, and the navigation a visitor may not use is absent rather than hidden.
// React renders this payload; it never re-derives it.

export type ChromeLink = {
  label: string;
  href: string;
};

export type ChromeBanner = {
  title: string | null;
  body: string;
};

/**
 * Present only while the session is authenticated through Emergency Access.
 * The server derives it from the signed session token, so a page cannot opt in
 * or out of it — see SurfaceChrome#chrome_restricted_mode.
 */
export type ChromeRestrictedMode = {
  label: string;
  description: string;
  sign_out: ChromeLink;
};

export type SurfaceChrome = {
  family_label: string | null;
  surface: string;
  brand: { name: string; href: string | null };
  banner: ChromeBanner | null;
  /** Non-null for a Restricted Mode (Emergency Access) session only. */
  restricted_mode: ChromeRestrictedMode | null;
  copyright: string;
};

/**
 * Props shared with every Inertia response of a surface, published to the adapter through
 * `InertiaConfig["sharedPageProps"]` in ./globals.d.ts so that a bare `usePage()` sees them.
 *
 * `errors` is deliberately absent: the adapter already declares it on `Page["props"]`, and the
 * server runs with `always_include_errors_hash`, so it is present on every response. Declaring it
 * here as well would produce a second, conflicting shape for the same payload.
 */
export type SharedProps = {
  chrome: SurfaceChrome;
  /** Set by a terminal ceremony so the persistent layout clears encrypted browser history. */
  clear_history?: boolean;
};
